package com.clavis.reader;
import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Native article text and images, with an explicit Website action. No publisher WebView. */
public class ArticleActivity extends MainActivity {
 ArticleContent narrated;String source;LinearLayout articleBody;TextView status;ScrollView articleScroll;boolean closed;int restoredScroll;
 @Override public void onCreate(Bundle state){super.onCreate(state);source=FeedStore.web(getIntent().getStringExtra("url"));screen="Reader";shell(getIntent().getStringExtra("title"));bar.getChildAt(0).setOnClickListener(v->finish());bar.removeViewAt(2);bar.addView(UiStyle.icon(this,R.drawable.ic_listen_audio,"Listen to article",()->{if(narrated!=null)Listen.article(this,"article:"+source,getIntent().getStringExtra("title"),StoryPages.text(narrated));},48));TextView website=button("Website",()->{if(!source.isEmpty())startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(source)));});website.setContentDescription("Open website in browser");website.setTextSize(13);website.setBackgroundColor(android.graphics.Color.TRANSPARENT);bar.addView(website,new LinearLayout.LayoutParams(-2,dp(40)));body.setPadding(dp(22),dp(18),dp(22),dp(36));articleScroll=(ScrollView)root.getChildAt(1);TextView title=text(getIntent().getStringExtra("title"),26,INK,true);body.addView(title);space(body,12);status=text("Loading article…",12,MUTED,false);body.addView(status);space(body,12);articleBody=column();body.addView(articleBody);String summary=getIntent().getStringExtra("summary");ArticleContent feed=ArticleContent.extract(summary==null?"":summary,source,true);render(feed);restoredScroll=state==null?0:state.getInt("articleScroll",0);io.execute(()->load(feed));}
 void load(ArticleContent fallback){try{ArticleContent ready=ArticleRepository.load(this,source,fallback);runOnUiThread(()->{if(closed||isDestroyed())return;render(ready);status.setText("Publisher preview · Open Website for access");status.setVisibility(ready.preview?View.VISIBLE:View.GONE);restoreScroll();});}catch(Exception e){runOnUiThread(()->{if(closed||isDestroyed())return;status.setText("Showing feed text. Website may have the complete article.");restoreScroll();});}}
 void restoreScroll(){articleScroll.post(()->{if(!closed)articleScroll.scrollTo(0,restoredScroll);});}
 void render(ArticleContent article){narrated=article;articleBody.removeAllViews();String lead=FeedStore.web(getIntent().getStringExtra("image"));HashSet<String> shownImages=new HashSet<>();boolean hasImages=article.blocks.stream().anyMatch(block->block.kind.equals("img"));if(!lead.isEmpty()&&!hasImages){shownImages.add(ArticleContent.imageKey(lead));image(lead);}for(ArticleContent.Block block:article.blocks){if(block.kind.equals("img")){if(shownImages.add(ArticleContent.imageKey(block.value)))image(block.value);continue;}boolean heading=block.kind.equals("heading"),caption=block.kind.equals("caption");TextView paragraph=text((block.kind.equals("li")?"•  ":"")+block.value,heading?22:caption?13:18,caption?MUTED:INK,heading);paragraph.setTextIsSelectable(true);paragraph.setLineSpacing(dp(4),1.12f);articleBody.addView(paragraph,new LinearLayout.LayoutParams(-1,-2));space(articleBody,heading?12:16);}}
 void image(String url){ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Article image");articleBody.addView(image,new LinearLayout.LayoutParams(-1,dp(230)));space(articleBody,12);FeedArtwork.bind(this,image,url);}
 File cacheFile()throws Exception{StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(source.getBytes(StandardCharsets.UTF_8)))hash.append(String.format(Locale.US,"%02x",b&255));File dir=new File(getCacheDir(),"article-text-v6");dir.mkdirs();return new File(dir,hash+".json");}
 static void write(File file,ArticleContent content)throws Exception{JSONArray blocks=new JSONArray();for(ArticleContent.Block b:content.blocks)blocks.put(new JSONObject().put("kind",b.kind).put("value",b.value));try(OutputStream out=new FileOutputStream(file)){out.write(new JSONObject().put("title",content.title).put("published",content.published).put("preview",content.preview).put("blocks",blocks).toString().getBytes(StandardCharsets.UTF_8));}}
 static ArticleContent read(File file)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(file)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>2*1024*1024)throw new IOException("Article cache too large");bytes.write(buffer,0,n);}}JSONObject json=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));ArticleContent content=new ArticleContent();content.title=json.optString("title");content.preview=json.optBoolean("preview");content.published=json.optString("published");JSONArray blocks=json.getJSONArray("blocks");for(int n=0;n<blocks.length();n++){JSONObject b=blocks.getJSONObject(n);content.add(b.getString("kind"),b.getString("value"));}return content;}
 @Override protected void onSaveInstanceState(Bundle state){state.putInt("articleScroll",articleScroll==null?0:articleScroll.getScrollY());super.onSaveInstanceState(state);}
 @Override public void onBackPressed(){finish();}
 @Override protected void onDestroy(){closed=true;super.onDestroy();}
}
